PS_Primitive.glsl:
vec4 PS_Primitive(vec4 position, vec4 color, vec2 tex_coord, float intensity, float fresnel, float depth_vol, vec3 tangent, vec3 binormal, vec3 normal, vec3 w_pos, vec3 s_pos, float parallax_scale, vec2 ouv, vec2 ouvx, vec2 ouvy, vec2 od, float oz, FOG_OUT fog_out) {
  FDepthTest(position);
  vec2 ddxy = (position.xy * CBScreen_fScreenInverseSize);
  FPrimitiveDepthComparison(ddxy, w_pos);
  vec4 f_color = color;
  vec2 uv = tex_coord;
  vec4 f_tex = vec4(0.0, 0.0, 0.0, 0.0);
  vec4 base_color = vec4(0.0, 0.0, 0.0, 0.0);
  vec4 mask_map = vec4(1.0, 1.0, 1.0, 1.0);
  vec3 w_normal = vec3(0.0, 0.0, 0.0);
  PRIM_EYE_OUT eye = FPrimitiveCalcEye(w_pos);
  uv = FPrimitiveUVClamp(uv);
  vec2 dx = dFdx(uv);
  vec2 dy = dFdy(uv);
  f_color.w = FPrimitivePSOcclusion(color.w, ouv, ouvx, ouvy, od, oz);
  uv = FPrimitiveParallax(eye, normal, tangent, binormal, parallax_scale, uv, dx, dy);
  f_tex = FPrimitiveSample(uv, dx, dy);
  f_tex.w = FPrimitiveSampleAlphaMap(f_tex.w, uv, dx, dy);
  f_tex = FPrimitiveSceneSampler(color, f_tex, intensity, ddxy, w_pos);
  base_color = FPrimitiveColTexInfluence(f_color, f_tex);
  mask_map = FPrimitiveMaskMap(uv, dx, dy);
  w_normal = FPrimitiveCalcNormalMap(normal, tangent, binormal, uv, dx, dy);
  base_color.xyz = FPrimitiveCalcDiffuse(w_normal, base_color.xyz);
  base_color.w = FPrimitiveCalcVolumeBlendPS(base_color.w, f_color.w, ddxy, s_pos, depth_vol);
  base_color = FPrimitiveCalcSpecular(base_color, eye, w_normal, mask_map, fresnel);
  base_color.xyz = FPrimitiveCalcShade(base_color.xyz, w_pos);
  base_color.xyz = FPrimitiveToneMap(base_color.xyz);
  base_color = FPrimitiveLevelCorrection(base_color);
  base_color = FPrimitiveCalcFogPS(base_color, fog_out);
  base_color = FPrimitiveAlphaToColor(base_color);
  FAlphaTest(base_color.w);
  return base_color;
}

