VS_Primitive.glsl:
PRIMITIVE_VS_OUTPUT VS_Primitive(PRIMITIVE_VS_INPUT I) {
  PRIMITIVE_VS_OUTPUT O = zero_PRIMITIVE_VS_OUTPUT();
  float occ_factor = FPrimitiveOcclusionFactor(O.ouv, O.ouvx, O.ouvy, O.od, O.oz);
  vec3 c_pos = FPrimitiveCalcPos(I);
  O.w_pos = c_pos;
  c_pos = FPrimitiveCalcPosVolumeBlendDepthVolume(I.prim_vol, c_pos);
  O.position = FViewProj(c_pos, vec2(0.0));
  O.position.z = calcZOffset(c_pos, I.zoffset, O.position.w);
  O.s_pos = O.position.xyz;
  O.s_pos.z = calcScreenZtoViewDepth((O.position.z / O.position.w));
  O.color = I.color;
  O.color.w = FPrimitiveCalcDepthBlend(c_pos, O.color.w);
  O.color.xyz = FPrimitiveCalcColorInt(I, O.color.xyz);
  O.color.w *= occ_factor;
  PRIM_FOG_OUT o_fog = FPrimitiveCalcFog(I.position, O.color, O.position);
  O.color = o_fog.color;
  O.fog = o_fog.fog;
  O.tex_coord = FPrimitiveCalcTexCoord(I.tex_coord);
  O.depth_vol = FPrimitiveCalcVolumeBlend(I.prim_vol);
  PRIM_NTB_OUT ntb = FPrimitiveCalcNTB(I);
  O.normal = ntb.normal;
  O.tangent = ntb.tangent;
  O.binormal = ntb.binormal;
  O.intensity = FPrimitiveCalcIntensity(I);
  O.fresnel = FPrimitiveCalcFresnel(c_pos, O.normal, CBViewProjection_fCameraPos);
  O.parallax_scale = FPrimitiveParallaxScale(I);
  O.position.w = FPrimitiveVSAlphaClip(O.position.w, O.color.w);
  return O;
}

