FPrimitiveCalcPosParticle.glsl:
vec3 FPrimitiveCalcPosParticle(PRIMITIVE_VS_INPUT I) {
  vec3 pos = vec3(0.0, 0.0, 0.0);
  vec2 posr = vec2(0.0, 0.0);
  vec3 pos2 = vec3(0.0, 0.0, 0.0);
  float scale = (I.spr_scale / 256.0);
  float rotz = convZValue(I.spr_rot);
  float sin_rz = sin(rotz);
  float cos_rz = cos(rotz);
  pos.xy = ((vec2(I.spr_w, I.spr_h) * 4.0) * scale);
  pos.x *= (I.spr_ratio / 16.0);
  posr.x = ((pos.x * cos_rz) - (pos.y * sin_rz));
  posr.y = ((pos.x * sin_rz) + (pos.y * cos_rz));
  return ((CBViewProjection_fViewI * vec4(posr, 0.0, 0.0)).xyz + I.position.xyz);
}

