  ouv *= intensity;
  ret.xyz = texture(tPrimSceneMap, FClampSceneUV((ddxy + (ouv * (0.0 / 7.0))))).xyz;
  ret.xyz += texture(tPrimSceneMap, FClampSceneUV((ddxy + (ouv * (1.0 / 7.0))))).xyz;
  ret.xyz += texture(tPrimSceneMap, FClampSceneUV((ddxy + (ouv * (2.0 / 7.0))))).xyz;
  ret.xyz += texture(tPrimSceneMap, FClampSceneUV((ddxy + (ouv * (3.0 / 7.0))))).xyz;
  ret.xyz += texture(tPrimSceneMap, FClampSceneUV((ddxy + (ouv * (4.0 / 7.0))))).xyz;
  ret.xyz += texture(tPrimSceneMap, FClampSceneUV((ddxy + (ouv * (5.0 / 7.0))))).xyz;
  ret.xyz += texture(tPrimSceneMap, FClampSceneUV((ddxy + (ouv * (6.0 / 7.0))))).xyz;
  ret.xyz += texture(tPrimSceneMap, FClampSceneUV((ddxy + (ouv * (7.0 / 7.0))))).xyz;
  ret.xyz /= 8.0;
